        self.tickets = self.parameters.get("tickets", [])

    def list_tickets(self):
        return {"success": True, "data": {"tickets": self.tickets}}

    def resolve_ticket(self, *, ticket_id):
        for ticket in self.tickets:
            if ticket.get("id") == ticket_id:
                ticket["status"] = "Resolved"
                return {"success": True}
        return {"success": False}

    def merge_tickets(self, *, primary_ticket_id, duplicate_ticket_id):
        primary_ticket = next((ticket for ticket in self.tickets if ticket["id"] == primary_ticket_id), None)
        duplicate_ticket = next((ticket for ticket in self.tickets if ticket["id"] == duplicate_ticket_id), None)
        if primary_ticket and duplicate_ticket:
            primary_ticket["description"] += " " + duplicate_ticket["description"]
            self.tickets.remove(duplicate_ticket)
